ALTER TABLE "setting_values" ADD CONSTRAINT "setting_values_qr_template_quiet_zone_check" CHECK (setting_key <> 'delivery.qr_template' OR jsonb_typeof(value) = 'null' OR (CASE WHEN jsonb_typeof(value -> 'quietZoneModules') = 'number' THEN ((value ->> 'quietZoneModules')::numeric BETWEEN 0 AND 16 AND (value ->> 'quietZoneModules')::numeric = trunc((value ->> 'quietZoneModules')::numeric)) ELSE false END));